import numpy as np
from autograd import Tensor
import gpt_ops_l2 as _G
from gpt_ops_l3 import init_weights, get_batch

W = _G.read_weights('gpt-w-embed.json', 'gpt-w-block0.json')
TRAIN = np.array(_G.encode(open('tiny-shakespeare.txt').read()[:225000]))
XB, YB = get_batch(TRAIN, 16, 32, np.random.default_rng(0))


def as_params(w):
    return {k: Tensor(np.array(v)) for k, v in w.items()}


def new_state():
    return {'t': 0, 'm': {}, 'v': {}}


def _one():
    P, s = as_params(W), new_state()
    first = train_step(P, s, (XB, YB), 1e-3)
    return first, _G.mean_loss({k: t.data for k, t in P.items()}, XB, YB), s['t']


def _three():
    P, s, rng = as_params(init_weights(0)), new_state(), np.random.default_rng(1)
    return [train_step(P, s, get_batch(TRAIN, 16, 32, rng), 3e-3) for _ in range(3)]
